`include "prim_assert.sv"

module hmac_reg_top (
  input clk_i,
  input rst_ni,
  input  tlul_pkg::tl_h2d_t tl_i,
  output tlul_pkg::tl_d2h_t tl_o,

  // Output port for window
  output tlul_pkg::tl_h2d_t tl_win_o,
  input  tlul_pkg::tl_d2h_t tl_win_i,

  // To HW
  output hmac_reg_pkg::hmac_reg2hw_t reg2hw, // Write
  input  hmac_reg_pkg::hmac_hw2reg_t hw2reg, // Read

  // Integrity check errors
  output logic intg_err_o
);

  import hmac_reg_pkg::* ;

  localparam int AW = 13;
  localparam int DW = 32;
  localparam int DBW = DW/8;                    // Byte Width

  // register signals
  logic           reg_we;
  logic           reg_re;
  logic [AW-1:0]  reg_addr;
  logic [DW-1:0]  reg_wdata;
  logic [DBW-1:0] reg_be;
  logic [DW-1:0]  reg_rdata;
  logic           reg_error;

  logic          addrmiss, wr_err;

  logic [DW-1:0] reg_rdata_next;
  logic reg_busy;

  tlul_pkg::tl_h2d_t tl_reg_h2d;
  tlul_pkg::tl_d2h_t tl_reg_d2h;


  // incoming payload check
  logic intg_err;
  tlul_cmd_intg_chk u_chk (
    .tl_i(tl_i),
    .err_o(intg_err)
  );

  // also check for spurious write enables
  logic reg_we_err;
  logic [58:0] reg_we_check;
  prim_reg_we_check #(
    .OneHotWidth(59)
  ) u_prim_reg_we_check (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .oh_i  (reg_we_check),
    .en_i  (reg_we && !addrmiss),
    .err_o (reg_we_err)
  );

  logic err_q;

assign intg_err_o = err_q | intg_err | reg_we_err;

// outgoing integrity generation
tlul_pkg::tl_d2h_t tl_o_pre;
tlul_rsp_intg_gen #(
  .EnableRspIntgGen(1),
  .EnableDataIntgGen(1)
) u_rsp_intg_gen (
  .tl_i(tl_o_pre),
  .tl_o(tl_o)
);

tlul_pkg::tl_h2d_t tl_socket_h2d [2];
tlul_pkg::tl_d2h_t tl_socket_d2h [2];

logic [0:0] reg_steer;

// socket_1n connection
assign tl_reg_h2d = tl_socket_h2d[1];
assign tl_socket_d2h[1] = tl_reg_d2h;

assign tl_win_o = tl_socket_h2d[0];
assign tl_socket_d2h[0] = tl_win_i;

// Create Socket_1n
tlul_socket_1n #(
  .N            (2),
  .HReqPass     (1'b1),
  .HRspPass     (1'b1),
  .DReqPass     ({2{1'b1}}),
  .DRspPass     ({2{1'b1}}),
  .HReqDepth    (4'h0),
  .HRspDepth    (4'h0),
  .DReqDepth    ({2{4'h0}}),
  .DRspDepth    ({2{4'h0}}),
  .ExplicitErrs (1'b0)
) u_socket (
  .clk_i  (clk_i),
  .rst_ni (rst_ni),
  .tl_h_i (tl_i),
  .tl_h_o (tl_o_pre),
  .tl_d_o (tl_socket_h2d),
  .tl_d_i (tl_socket_d2h),
  .dev_select_i (reg_steer)
);

always_comb begin
  reg_steer =
      tl_i.a_address[AW-1:0] inside {[4096:8191]} ? 1'd0 :
      // Default set to register
      1'd1;

  // Override this in case of an integrity error
  if (intg_err) begin
    reg_steer = 1'd1;
  end
end

tlul_adapter_reg #(
  .RegAw(AW),
  .RegDw(DW),
  .EnableDataIntgGen(0)
) u_reg_if (
  .clk_i  (clk_i),
  .rst_ni (rst_ni),

  .tl_i (tl_reg_h2d),
  .tl_o (tl_reg_d2h),

  .en_ifetch_i(prim_mubi_pkg::MuBi4False),
  .intg_error_o(),

  .we_o    (reg_we),
  .re_o    (reg_re),
  .addr_o  (reg_addr),
  .wdata_o (reg_wdata),
  .be_o    (reg_be),
  .busy_i  (reg_busy),
  .rdata_i (reg_rdata),
  .error_i (reg_error)
);

// cdc oversampling signals

assign reg_rdata = reg_rdata_next ;
assign reg_error = addrmiss | wr_err | intg_err;

